from z3 import *
import itertools

def solve_ramsey():
    n = 21
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((i, j))

    edge_vars = {}
    for i, j in edges:
        edge_vars[(i, j)] = Int(f'e_{i}_{j}')

    solver = Solver()

    # Edge variables are 0 or 1
    for var in edge_vars.values():
        solver.add(Or(var == 0, var == 1))

    # No red K5 (0)
    # For every subset of 5 vertices, at least one edge must be 1 (blue)
    for subset in itertools.combinations(range(n), 5):
        red_edges = []
        for i, j in itertools.combinations(subset, 2):
            if i < j:
                red_edges.append(edge_vars[(i, j)] == 0)
            else:
                red_edges.append(edge_vars[(j, i)] == 0)
        solver.add(Not(And(*red_edges)))

    # No blue K4 (1)
    # For every subset of 4 vertices, at least one edge must be 0 (red)
    for subset in itertools.combinations(range(n), 4):
        blue_edges = []
        for i, j in itertools.combinations(subset, 2):
            if i < j:
                blue_edges.append(edge_vars[(i, j)] == 1)
            else:
                blue_edges.append(edge_vars[(j, i)] == 1)
        solver.add(Not(And(*blue_edges)))

    if solver.check() == sat:
        model = solver.model()
        result = []
        for i, j in edges:
            result.append(model.evaluate(edge_vars[(i, j)]).as_long())
        return result
    else:
        return None

